'use strict';

// MODULES //

var isUndefinedOrNull = require( '@stdlib/assert/is-undefined-or-null' );


// FUNCTIONS //

/**
* Returns the string representation of an array element.
*
* @private
* @param {Function} get - accessor function
* @param {Collection} xbuf - data buffer
* @param {integer} idx - element index
* @returns {string} string representation
*/
function str( get, xbuf, idx ) {
	var v = get( xbuf, idx );
	if ( isUndefinedOrNull( v ) ) {
		return '';
	}
	return String( v );
}


// MAIN //

/**
* Returns a string created by joining strided array elements using a conjunction.
*
* @private
* @param {PositiveInteger} N - number of indexed elements
* @param {string} prefix - string to prepend
* @param {string} suffix - string to append
* @param {string} conjunction - conjunction before the last element
* @param {boolean} oxfordComma - boolean specifying whether to include an Oxford comma
* @param {Object} x - input array object
* @param {Collection} x.data - input array data
* @param {Array<Function>} x.accessors - array element accessors
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @returns {string} joined string
*
* @example
* var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
* var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
*
* var x = [ 1, 2, 3, 4 ];
*
* var out = gconjoin( x.length, '', '', 'and', true, arraylike2object( toAccessorArray( x ) ), 1, 0 );
* // returns '1, 2, 3, and 4'
*/
function gconjoin( N, prefix, suffix, conjunction, oxfordComma, x, strideX, offsetX ) { // eslint-disable-line max-len
	var xbuf;
	var out;
	var get;
	var ix;
	var i;

	// Cache reference to array data:
	xbuf = x.data;

	// Cache a reference to the element accessor:
	get = x.accessors[ 0 ];

	// First element...
	ix = offsetX;
	out = prefix + str( get, xbuf, ix );
	ix += strideX;

	// Middle elements...
	for ( i = 1; i < N - 1; i++ ) {
		out += ', ' + str( get, xbuf, ix );
		ix += strideX;
	}

	// Last element (when N >= 2)...
	if ( N >= 2 ) {
		if ( conjunction === '' ) {
			out += ', ' + str( get, xbuf, ix );
		} else if ( N >= 3 && oxfordComma ) {
			out += ', ' + conjunction + ' ' + str( get, xbuf, ix );
		} else {
			out += ' ' + conjunction + ' ' + str( get, xbuf, ix );
		}
	}
	return out + suffix;
}


// EXPORTS //

module.exports = gconjoin;
